const { evaluate, ExprError } = require('./src/index');
const assert = require('node:assert/strict');

// precedence / associativity
assert.equal(evaluate('-2 ** 2'), -4);
assert.equal(evaluate('2 ** -1'), 0.5);
assert.equal(evaluate('2 ** 3 ** 2'), 512);
assert.equal(evaluate('-2 ** 2 ** 3'), -256);
assert.equal(evaluate('2 * 3 ** 2'), 18);
assert.equal(evaluate('1 + 2 - 3 + 4'), 4);
assert.equal(evaluate('8 // 3 * 3'), 6);

// floor div / mod
assert.equal(evaluate('-7 // 2'), -4);
assert.equal(evaluate('-7 % 3'), 2);
assert.equal(evaluate('7 % -3'), -2);
assert.equal(evaluate('-7 // -2'), 3);
assert.equal(evaluate('-7 % -3'), -1);
assert.equal(evaluate('7.5 // 2'), 3);
assert.equal(evaluate('-7.5 // 2'), -4);
assert.equal(evaluate('7.5 % 2.5'), 0);
assert.equal(evaluate('5.5 % -1.5'), -0.5);
assert.ok(Object.is(evaluate('-4 % 2'), 0)); // positive zero
assert.ok(Object.is(evaluate('-4 // 2'), -2));

// comparisons chain
assert.equal(evaluate('1 < 2 <= 2'), true);
assert.equal(evaluate('1 < 2 <= 1'), false);
assert.equal(evaluate('3 > 2 > 1'), true);
assert.equal(evaluate('1 < 2 < 2'), false);
assert.equal(evaluate('1 == 1 != 2'), true);
assert.equal(evaluate('(1 < 2) + 1'), 2);
assert.equal(evaluate('(2 < 1) * 5'), 0);
assert.equal(evaluate('(1 < 2) == 1'), true);
assert.equal(evaluate('min(3, 1, 2)'), 1);
assert.equal(evaluate('max(3, 1, 2)'), 3);
assert.equal(evaluate('abs(-5)'), 5);

// short-circuit: remaining operands not evaluated (getter not read)
{
  let reads = 0;
  const vars = {};
  Object.defineProperty(vars, 'x', { get() { reads++; return 1; } });
  Object.defineProperty(vars, 'y', { get() { reads++; return 0; } });
  assert.equal(evaluate('x > 1 < y', vars), false);
  assert.equal(reads, 1); // y never read
}
// each occurrence read once, left-to-right
{
  const log = [];
  const vars = {};
  Object.defineProperty(vars, 'a', { get() { log.push('a'); return 2; } });
  Object.defineProperty(vars, 'b', { get() { log.push('b'); return 3; } });
  assert.equal(evaluate('a + b * a', vars), 8);
  assert.deepEqual(log, ['a', 'b', 'a']);
}

// variables
assert.equal(evaluate('x + 1', { x: 41 }), 42);

// error columns
const col = (src, vars) => { try { evaluate(src, vars); } catch (e) { return e.column; } throw new Error('no error'); };
assert.equal(col('1 + @'), 5);
assert.equal(col('  1 + @'), 7);
assert.equal(col('1 +'), 4);            // unexpected end = length+1
assert.equal(col('1 +   '), 7);         // trailing whitespace counted
assert.equal(col('q + 1'), 1);          // unknown variable at identifier
assert.equal(col('  q + 1'), 3);
assert.equal(col('1 // 0'), 3);         // at operator token
assert.equal(col('1 % (1 - 1)'), 3);
assert.equal(col('foo(1)'), 1);         // unknown call at identifier
assert.equal(col('abs(1, 2)'), 1);      // wrong arity at identifier
assert.equal(col('min()'), 1);
assert.equal(col('(1 + 2'), 7);
assert.equal(evaluate('1 < 2') === true, true);

// getter read once even for booleans in arithmetic
console.log('all semantic checks passed');
"

